-- STAGING ONLY 473: complete missing Navision WMI from authenticated PDF only when VDS+frame suffix agrees; exact UID632 retry.
BEGIN;SET LOCAL lock_timeout='10s';SET LOCAL statement_timeout='180s';SELECT pg_advisory_xact_lock(hashtextextended('pdc-staging-473-pdf-vin-suffix-uid632-retry',0));
DO $guard$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' OR (SELECT count(*) FROM public.pdc_staging_environment_sentinel WHERE singleton AND project_ref='cdsmnqxtyyoeoznmbidd')<>1 OR to_regclass('public.pdc_production_environment_sentinel') IS NOT NULL OR NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20260827022000' AND name='472_effective_navision_vin_import_uid632_retry') OR EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version~'^[0-9]{14}$' AND version>'20260827022000') OR encode(extensions.digest(convert_to(pg_get_functiondef('public.import_pdc_authenticated_vehicle_email(text,text,text,text,text,jsonb,timestamptz,text,jsonb,jsonb)'::regprocedure),'UTF8'),'sha256'),'hex')<>'fca58e2fbf9fd1b324f3bd0c888d7d4f134f7122f41275705ee92aa769958713' OR NOT EXISTS(SELECT 1 FROM public.ai_email_intake WHERE id='57de2d60-16f8-480c-89b3-c69505f5fb88'::uuid AND provider_uid='imap_uid:632' AND status='needs_review') OR NOT EXISTS(SELECT 1 FROM public.pdc_email_attachment_batch_receipts_323 WHERE batch_receipt_id='45b375ca-1c35-4928-8789-a6a36b65d9fc'::uuid AND result_sha256='154b289c0fcf7839296112efafcd592e3dff76618a2bee2ffab27ae2d1193e0e') THEN RAISE EXCEPTION 'PDC_473_TARGET_HEAD_FUNCTION_OR_UID632_EVIDENCE_MISMATCH' USING errcode='55000';END IF;END $guard$;
CREATE FUNCTION public.pdc_authenticated_pdf_matches_navision_suffix_473(p_data jsonb,p_pdf_vin text) RETURNS boolean LANGUAGE sql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $match$ WITH x AS(SELECT public.normalize_vehicle_vin(p_pdf_vin) pdf,public.normalize_vehicle_vin(p_data->>'vin') raw,public.normalize_vehicle_vin(coalesce(p_data->>'vdsNumber','')||coalesce(p_data->>'frame','')) parts) SELECT public.is_valid_vehicle_vin(pdf) AND ((public.pdc_navision_effective_vin_471(p_data)=pdf) OR (length(raw)=14 AND right(pdf,14)=raw AND parts=raw)) FROM x $match$;REVOKE ALL ON FUNCTION public.pdc_authenticated_pdf_matches_navision_suffix_473(jsonb,text) FROM public,anon,authenticated,service_role;
DO $patch$ DECLARE d text;p text;BEGIN d:=pg_get_functiondef('public.import_pdc_authenticated_vehicle_email(text,text,text,text,text,jsonb,timestamptz,text,jsonb,jsonb)'::regprocedure);p:=replace(d,'if v_extracted_vin is not null and v_vehicle.vin_normalized is not null and v_vehicle.vin_normalized<>v_extracted_vin and public.pdc_navision_effective_vin_471(v_record.normalized_data) is distinct from v_extracted_vin then return public.navision_backend_response(false,''vin_conflict_non_authoritative''); end if;','if v_extracted_vin is not null and v_vehicle.vin_normalized is distinct from v_extracted_vin then if public.pdc_authenticated_pdf_matches_navision_suffix_473(v_record.normalized_data,v_extracted_vin) and (v_vehicle.vin_normalized is null or v_vehicle.vin_normalized=public.normalize_vehicle_vin(v_record.normalized_data->>''vin'')) then if exists(select 1 from public.vehicles x where x.id<>v_vehicle.id and x.vin_normalized=v_extracted_vin) or exists(select 1 from public.vehicle_aliases a where a.vehicle_id<>v_vehicle.id and a.active and a.alias_type_normalized=''vin'' and a.normalized_alias_value=v_extracted_vin) then return public.navision_backend_response(false,''operational_vin_owner_conflict''); end if; v_before_vehicle:=to_jsonb(v_vehicle); update public.vehicles set vin=v_extracted_vin,version=version+1,updated_by=v_actor_id,updated_at=clock_timestamp() where id=v_vehicle.id returning * into v_vehicle; insert into public.audit_events(action,table_name,row_id,vehicle_id,actor_id,actor_email,before_data,after_data,metadata) values(''update'',''vehicles'',v_vehicle.id,v_vehicle.id,v_actor_id,v_actor_email,v_before_vehicle,to_jsonb(v_vehicle),jsonb_build_object(''source'',''authenticated_pdf_navision_suffix_473'',''source_hash'',v_source_hash,''backend_record_id'',v_record.id,''stock_number'',v_stock,''navision_suffix'',v_record.normalized_data->>''vin'',''pdf_full_vin_completed'',true,''booking_created'',false)); else return public.navision_backend_response(false,''vin_conflict_non_authoritative''); end if; end if;');IF p=d OR p NOT LIKE '%authenticated_pdf_navision_suffix_473%' THEN RAISE EXCEPTION 'PDC_473_IMPORT_PATCH_ANCHOR_MISSING' USING errcode='55000';END IF;EXECUTE p;END $patch$;
CREATE TEMP TABLE pdc_473_original_immutable(definition text NOT NULL) ON COMMIT DROP;INSERT INTO pdc_473_original_immutable VALUES(pg_get_functiondef('public.pdc_email_attachment_batch_receipt_immutable_323()'::regprocedure));CREATE OR REPLACE FUNCTION public.pdc_email_attachment_batch_receipt_immutable_323() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$BEGIN IF tg_op='DELETE' AND old.batch_receipt_id='45b375ca-1c35-4928-8789-a6a36b65d9fc'::uuid THEN RETURN old;END IF;RAISE EXCEPTION 'PDC_ATTACHMENT_BATCH_RECEIPT_IMMUTABLE_323' USING errcode='55000';END$$;
INSERT INTO public.pdc_email_attachment_batch_superseded_325(batch_receipt_id,intake_id,actor_id,gateway_instance_id,result,result_sha256,original_created_at,superseded_reason) SELECT batch_receipt_id,intake_id,actor_id,gateway_instance_id,result,result_sha256,created_at,'technical_authenticated_pdf_navision_suffix_fix_473' FROM public.pdc_email_attachment_batch_receipts_323 WHERE batch_receipt_id='45b375ca-1c35-4928-8789-a6a36b65d9fc'::uuid;DELETE FROM public.pdc_email_attachment_batch_receipts_323 WHERE batch_receipt_id='45b375ca-1c35-4928-8789-a6a36b65d9fc'::uuid;DO $restore$ DECLARE d text;BEGIN SELECT definition INTO d FROM pdc_473_original_immutable;EXECUTE d;END $restore$;
UPDATE public.ai_email_intake SET status='received',locked_at=null,locked_by=null,claim_token=null,processing_result='{}'::jsonb,next_attempt_at=clock_timestamp(),permanent_failure=false,retry_class=null,last_error_code=null,error_details=null,updated_at=clock_timestamp() WHERE id='57de2d60-16f8-480c-89b3-c69505f5fb88'::uuid AND provider_uid='imap_uid:632' AND status='needs_review';
DO $post$ BEGIN IF NOT public.pdc_authenticated_pdf_matches_navision_suffix_473(jsonb_build_object('vin','MABAV402402341','vdsNumber','MABAV4','frame','02402341'),'MR0MABAV402402341') OR EXISTS(SELECT 1 FROM public.pdc_email_attachment_batch_receipts_323 WHERE batch_receipt_id='45b375ca-1c35-4928-8789-a6a36b65d9fc'::uuid) OR NOT EXISTS(SELECT 1 FROM public.ai_email_intake WHERE id='57de2d60-16f8-480c-89b3-c69505f5fb88'::uuid AND status='received') THEN RAISE EXCEPTION 'PDC_473_POSTCONDITION_FAILED' USING errcode='55000';END IF;END $post$;
INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES('20260827023000','473_authenticated_pdf_navision_suffix_uid632_retry',ARRAY['Complete a missing Navision WMI only when authenticated PDF full VIN ends with the exact Navision VIN suffix and Navision VDS plus frame reproduces that suffix','Reject conflicting valid operational or alias VIN owners and preserve exact Stock authority','Preserve three prior UID632 review outcomes as superseded evidence and retry only the exact owner email','Production untouched']);NOTIFY pgrst,'reload schema';COMMIT;
